sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float sweep;
uniform float alpha;
uniform float bias;
uniform float r;
uniform float g;
uniform float b;
uniform float a;
float pick(float m, float lo, float hi, float avg, float src) {
    return m < 0.5 ? lo : m < 1.5 ? hi : m < 2.5 ? avg : src;
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float2 c = center * size;
    float span = radians(sweep);
    if (span <= 0.0) return src;
    float2 d = coord - c;
    float4 hi = float4(0.0);
    float4 sum = float4(0.0);
    float4 lo = float4(1.0);
    for (int i = 0; i < 48; i++) {
        float t = span * 0.5 * mix(bias - 1.0, bias + 1.0, float(i) / 47.0);
        float cs = cos(t);
        float sn = sin(t);
        float4 v = float4(image.eval(c + float2(cs * d.x - sn * d.y, sn * d.x + cs * d.y)));
        hi = max(hi, v);
        sum += v;
        lo = min(lo, v);
    }
    float4 avg = sum / 48.0;
    float4 s = float4(src);
    float4 acc = float4(pick(r, lo.r, hi.r, avg.r, s.r), pick(g, lo.g, hi.g, avg.g, s.g), pick(b, lo.b, hi.b, avg.b, s.b), pick(a, lo.a, hi.a, avg.a, s.a));
    return half4(mix(s, acc, clamp(alpha, 0.0, 1.0)));
}
